```cpp
#include <iostream>
#include <cstring>
#include <cstdio>
#include <vector>

using namespace std;

typedef long long LL;
const int N = 20, P = 1e9 + 7;

int f0[N][15][10][10], f1[N][15][10][10], f2[N][15][10][10];
int pow10[0];

int get(int x, int y){
    return (y - x % 7 + 7) % 7;
}

void init(){
    pow10[0] = 1;
    for(int i = 1; i < N; i ++)
        pow10[i] = (LL)pow10[i - 1] * 10 % P;
    for(int i = 0; i <= 9; i ++){//len == 1初始化
        if(i == 7)continue;
        f0[1][i][i % 7][i % 7] = 1;
        f1[1][i][i % 7][i % 7] = i;
        f2[1][i][i % 7][i % 7] = i * i;
    }
    for(int i = 2; i <= 19; i ++){
        for(int j = 0; j <= 9; j ++){
            if(j == 7)continue;
            for(int a = 0; a <= 6; a ++){
                for(int p = 0; p <= 6; p ++){
                    for(int k = 0; k <= 9; k ++){
                        if(k == 7)continue;

                        int t = f0[i - 1][k][get(j, a)][get(j * pow10[i - 1], p)];
                        int sig1 = f1[i - 1][k][get(j, a)][get(j * pow10[i - 1], p)];
                        int sig2 = f2[i - 1][k][get(j, a)][get(j * pow10[i - 1], p)];

                        f0[i][j][a][p] += t;
                        f1[i][j][a][p] += t * j * pow10[i - 1] + sig1;
                        f2[i][j][a][p] += ((LL)(j * pow10[i - 1] % P) * (j * pow10[i - 1] % P) % P * t
                                        + (LL)2 * j * pow10[i - 1] * sig1 % P
                                        + sig2) % P;
                        f0[i][j][a][p] %= P;
                        f1[i][j][a][p] %= P;
                        f2[i][j][a][p] %= P;
                    }
                }
            }
        }
    }
}

int dp(LL n){
    LL back_n = n;
    // printf("n : %lld\n", n);
    if(n == 0)return 0;

    vector<int> nums;
    while(n)nums.push_back(n % 10), n /= 10;

    // printf("size : %d\n", nums.size());

    int res = 0, lasa = 0, lasp = 0;
    LL las = 0;
    for(int i = nums.size() - 1; i >= 0; i --){
        int x = nums[i];

        // printf("i : %d x : %d \n",i,  x);

        for(int j = 0; j < x; j ++){
            if(j == 7)continue;
            for(int a = 1; a <= 6; a ++){
                for(int p = 1; p <= 6; p ++){
                    int t = f0[i + 1][j][get(lasa, a)][get(lasp, p)];
                    int sig1 = f1[i + 1][j][get(lasa, a)][get(lasp, p)];
                    int sig2 = f2[i + 1][j][get(lasa, a)][get(lasp, p)];
                    res = (res
                              + ((LL)(las * pow10[i + 1] % P) * (las * pow10[i + 1] % P) % P * t
                              + (LL)2 * j * pow10[i - 1] * sig1 % P
                              + sig2) % P
                          ) % P;
                }
            }
        }

        if(!i && x != 7 && (lasa + x) % 7 != 0 && (lasp + x) % 7 != 0){
            // printf("last : %lld\n", (back_n % P) * (back_n % P));
            res = (res + (back_n % P) * (back_n % P) % P) % P;
        }

        if(x != 7){
            lasa = (lasa + x) % 7;
            lasp = (lasp + x * pow10[i]) % 7;
            las = las * 10 + x;
        }
        else break;

        // printf("lasa : %d lasp : %d res : %d\n", lasa, lasp, res);
    }

    return res;
}

int main(){
    init();

    int T;
    scanf("%d", &T);

    while(T --){
        LL l, r;
        scanf("%lld%lld", &l, &r);
        printf("%lld\n",dp(r) - dp(l - 1));
    }

    return 0;
}
```

*原题*：[混合背包问题](https://www.acwing.com/problem/content/7/)
---
在本题中  n ∈ [1, 1000], m ∈ [1, 2000], s ∈ [1, 2000]  

若使用传统多重背包写法：  
*三重循环嵌套-时间复杂度为:*  
*枚举n件物品 * 枚举背包体积v * 每件物品数s*  
时间复杂度$O(nms)$ $\quad$这显然是我们不可以接受的

但是每次第三层循环都要从$1->s$把物品所有可能数量枚举一遍  
或许我们可以考虑将$s$件物品等效，使得$s$的数量减少，且原本可以由s件物品选出的$i$仍可以被表示出  
我们考虑将s打包为$ {1,2,4,8...Ai} $ 使得  
$∑ai = s$ 则任意数 $∈ [1, s]$ 均可由a中数字组合得出  
于是将其打包成物品集合$a$
跑一遍01背包即可

```cpp
//算法提高课背包dp
//混合背包化作多重背包

