//11/26 10/13 WA : 二进制优化
//11/26 Ac : 个数开到nlogn 即 N = log1e3 * 1e3 ~= 1e4

#include<iostream>
#include<cstdio>

using namespace std;

const int N = 1e4 + 10;

int n, m;
int f[N], v[N], w[N], s[N], cnt = 0;

int main(){
    freopen("bag.in", "r", stdin);
    freopen("bag.out", "w", stdout);

    scanf("%d%d", &n, &m);
    for(int i = 1; i <= n; i ++){
        int W, V, S;
        scanf("%d%d%d", &W, &V, &S);
        if(S == -1)S = 1;
        else if(S == 0)S = m / W;

        int k = 1;
        while(k <= S){
            w[++cnt] = k * W;
            v[cnt] = k * V;
            S -= k;
            k *= 2;
        }
        if(S){
            w[++cnt] = S * W;
            v[cnt] = S * V;
        }
    }

    n = cnt;

    for(int i = 1; i <= n; i ++){
        for(int j = m; j >= w[i]; j --){
            f[j] = max(f[j], f[j - w[i]] + v[i]); 
        }
    }

    printf("%d", f[m]);

    return 0;
}
